const raw = $json.output ?? $json.answer ?? $json.text ?? "";
let parsed = raw;
if (typeof raw === "string") {
  const cleaned = raw.replace(/^```json\s*/i, "").replace(/```$/i, "").trim();
  try { parsed = JSON.parse(cleaned); } catch { parsed = { answer: cleaned }; }
}
const allow = ["happy", "thinking", "searching", "sorry", "welcome"];
const expression = allow.includes((parsed.expression || "").toLowerCase()) ? parsed.expression.toLowerCase() : "sorry";
const answer = parsed.answer || parsed.message || "ขออภัยครับ ไม่พบข้อมูล";
const mascot = parsed.mascot || "GuayJub";
const source = parsed.source || "n8n";
return [{ json: { output: answer, mascot, expression, answer, source } }];
